{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Codeine, the closest structural analogue sharing the methoxy-morphinan scaffold, has an absolute oral bioavailability of 42–71% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Codeine absolute oral bioavailability was 40 ± 22% even in postoperative patients, remaining above the 20% threshold and confirming the scaffold's oral systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ethylmorphine, a close N-ethyl analogue, showed a minimum oral availability median of 0.74 (range 0.54–0.92) in healthy subjects, strongly supporting high oral bioavailability for this morphinan family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Morphine, the phenolic analogue, had an absolute oral bioavailability of 32% in healthy volunteers, above the 20% threshold and consistent with the morphinan scaffold being orally bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Noscapine, a more distant morphinan, had a mean absolute oral bioavailability of 30% (range 16–58%), with the central estimate above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Cepharanthine, a bulky bisbenzylisoquinoline alkaloid, has low absolute oral bioavailability of 6–9%, but its very different structure and low similarity to the query limit transferability of this low-F result.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a methoxy-substituted morphinan alkaloid most closely related to codeine. Codeine and its close analogues consistently show absolute oral bioavailability well above 20% (approximately 40–90%), while the low-bioavailability examples are structurally distant. Therefore, F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "Fasted-state-specific data are limited; several analogue values come from patients or unspecified prandial conditions.",
    "The highest-similarity analogue has a Morgan score of only 0.4058, so structural transfer is strong but not exact."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

